  function notify(title, detail='') {
    const region = $('#toast-region');
    const item = document.createElement('div'); item.className='toast';
    item.innerHTML = `${escapeHtml(title)}${detail ? `<small>${escapeHtml(detail)}</small>` : ''}`;
    region.append(item); setTimeout(()=>item.remove(),3500);
  }
  function btn(label, action, cls='btn', iconName='') { return `<button class="${cls}" data-action="${action}">${iconName ? icon(iconName) : ''}${label}</button>`; }
  function navButton([id,label,ico], active=state.page, cls='nav-item') { return `<button class="${cls} ${active===id?'active':''}" data-page="${id}" aria-current="${active===id?'page':'false'}">${icon(ico)}<span>${label}</span></button>`; }
  function skinFigure() { return `<div class="skin-figure" aria-label="Custom Minecraft skin preview"><div class="skin-head"></div><div class="skin-body"></div><div class="skin-arm left"></div><div class="skin-arm right"></div><div class="skin-leg left"></div><div class="skin-leg right"></div><div class="skin-boot left"></div><div class="skin-boot right"></div></div>`; }
