    return `${pageIntro('More','Additional launcher tools and preferences. Native services are not connected in this preview.')}<section class="card"><div class="list">${rows.map(([name,desc,ico,page])=>`<button class="list-row more-row" data-page="${page}"><span class="feature-icon">${icon(ico)}</span><span class="row-main"><strong>${name}</strong><small>${desc}</small></span>${icon('chevron')}</button>`).join('')}</div></section><div class="preview-badge" style="margin-top:14px"><i class="preview-dot"></i> UI Preview · Demo data only</div>`;
